    placements = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = frozenset(((r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)))
            if square <= ink:
                placements.append((square, 1))
                for missing, color in (((r, c), 2), ((r + 1, c), 3),
                                       ((r, c + 1), 4), ((r + 1, c + 1), 5)):
                    tri = square - {missing}
                    placements.append((frozenset(tri), color))
    covering = {p: [] for p in ink}
    for cells, color in placements:
        for p in cells:
            covering[p].append((cells, color))

    def search(remaining, chosen):
        if not remaining:
            return chosen
        p = min(remaining, key=lambda q: sum(cells <= remaining for cells, _ in covering[q]))
        for cells, color in covering[p]:
            if cells <= remaining:
                result = search(remaining - cells, chosen + [(cells, color)])
                if result is not None:
                    return result
        return None

    tiling = search(ink, [])
    if tiling is None:
        raise ValueError("8-cells cannot be tiled by the demonstrated pieces")
    out = [[0 for _ in range(w)] for _ in range(h)]
    for cells, color in tiling:
        for r, c in cells:
            out[r][c] = color
    return out
